import { describe, expect, it } from "vitest";
import { PROVIDER_INTEGRATION_RECORDS } from "@t3tools/shared/providerIntegrationCertification";
import {
  chromeLaunchDecision,
  claudeChromeDescriptor,
  parseChromeRegistryQuery,
  parseNativeHostManifest,
  parseShellToken,
  verifyClaudeChromeServer,
  verifyClaudeWrapper,
  type ChromeNativeHostDescriptor,
} from "./chromeNativeHost";

const HEADER = [
  "#!/bin/sh",
  "# Chrome native host wrapper script",
  "# Generated by Claude Code - do not edit manually",
];
const EXE = "/bundle/claude";
const realpath = async (path: string) => {
  if (path === EXE || path === "/link/claude") return EXE;
  if (path === "/it's here/claude") return "/it's here/claude";
  throw Object.assign(new Error("missing"), { code: "ENOENT" });
};
const wrapper = (token: string, rest = "--chrome-native-host") =>
  `${HEADER.join("\n")}\nexec ${token} ${rest}\n`;
const verify = (bytes: string, executable = EXE) =>
  verifyClaudeWrapper(bytes, HEADER, ["--chrome-native-host"], executable, realpath);

describe("wrapper verification is the exact inverse of the CLI's quoting", () => {
  it("parses bare and single-quoted tokens and rejects everything else", () => {
    expect(parseShellToken("/bundle/claude")).toBe("/bundle/claude");
    expect(parseShellToken(`'/it'"'"'s here/claude'`)).toBe("/it's here/claude");
    expect(parseShellToken(`"/bundle/claude"`)).toBeUndefined();
    // The CLI never quotes a token that could stay bare.
    expect(parseShellToken(`'/bundle/claude'`)).toBeUndefined();
    expect(parseShellToken(`'/a b'x`)).toBeUndefined();
  });
  it.each([
    ["bare path", wrapper(EXE), true],
    ["symlink to the same realpath", wrapper("/link/claude"), true],
    ["extra command", wrapper(EXE, "--chrome-native-host; rm -rf ~"), false],
    ["double quotes", wrapper(`"${EXE}"`), false],
    ["wrong path", wrapper("/other/claude"), false],
    ["missing trailing newline", wrapper(EXE).slice(0, -1), false],
    ["second exec line", `${wrapper(EXE)}exec /bin/sh\n`, false],
    ["edited header", wrapper(EXE).replace("do not edit", "edit"), false],
  ])("%s", async (_name, bytes, expected) => {
    expect(await verify(bytes)).toBe(expected);
  });
  it("accepts a quoted path containing a single quote", async () => {
    expect(await verify(wrapper(`'/it'"'"'s here/claude'`), "/it's here/claude")).toBe(true);
  });
});

describe("Claude in Chrome server provenance", () => {
  const expected = { serverName: "claude-in-chrome", mcpArgs: ["--claude-in-chrome-mcp"] };
  const context = { executableRealpath: EXE, toolNames: ["read_page", "navigate"], realpath };
  const base = { name: "claude-in-chrome", status: "connected", scope: "dynamic" };
  it.each([
    ["config absent", base, true],
    [
      "config present",
      {
        ...base,
        config: { type: "stdio", command: "/link/claude", args: ["--claude-in-chrome-mcp"] },
      },
      true,
    ],
    ["source dynamic", { name: "claude-in-chrome", status: "connected", source: "dynamic" }, true],
    ["wrong source", { name: "claude-in-chrome", status: "connected", source: "project" }, false],
    ["pending", { ...base, status: "pending" }, false],
    [
      "extra args",
      { ...base, config: { command: EXE, args: ["--claude-in-chrome-mcp", "--x"] } },
      false,
    ],
    [
      "wrong command",
      { ...base, config: { command: "/other", args: ["--claude-in-chrome-mcp"] } },
      false,
    ],
    ["unknown tool", { ...base, tools: [{ name: "read_page" }, { name: "exfiltrate" }] }, false],
    ["known tools", { ...base, tools: [{ name: "read_page" }] }, true],
    ["lookalike name", { ...base, name: "claude-in-chrome2" }, false],
  ])("%s", async (_name, status, ok) => {
    expect(await verifyClaudeChromeServer(status, expected, context)).toBe(ok);
  });
});

describe("Chrome launch decision", () => {
  const record = PROVIDER_INTEGRATION_RECORDS["claude-chrome"][0]!;
  const descriptor: ChromeNativeHostDescriptor = claudeChromeDescriptor(record);
  const target = descriptor.expectedTarget("/profile/claude");
  const manifest = (path: string) =>
    JSON.stringify({ name: record.identity.hostName, type: "stdio", allowed_origins: [], path });
  const base = {
    enabled: true,
    certified: true,
    descriptor,
    providerHome: "/profile/claude",
    profileId: "p",
    providerInstanceId: "claudeAgent",
  };
  it("asks about foreign setup, including another F5 profile's wrapper", () => {
    const registrations = [
      parseNativeHostManifest(
        "chrome",
        "a",
        manifest("/other-profile/claude/chrome/chrome-native-host"),
      ),
    ];
    expect(chromeLaunchDecision({ ...base, registrations })).toMatchObject({
      kind: "needs-consent",
      previousTargets: ["/other-profile/claude/chrome/chrome-native-host"],
    });
  });
  it("never re-prompts for unchanged setup of this instance", () => {
    expect(
      chromeLaunchDecision({
        ...base,
        registrations: [parseNativeHostManifest("chrome", "a", manifest(target))],
      }),
    ).toEqual({ kind: "launch", targetPath: target });
  });
  it("reuses consent only for the same profile, instance, target and exact foreign bytes", () => {
    const foreign = parseNativeHostManifest("chrome", "a", manifest("/foreign"));
    const accepted = {
      profileId: "p",
      providerInstanceId: "claudeAgent",
      targetPath: target,
      acceptedForeign: [{ location: "a", sha256: foreign.sha256! }],
    };
    expect(chromeLaunchDecision({ ...base, registrations: [foreign], accepted }).kind).toBe(
      "launch",
    );
    expect(
      chromeLaunchDecision({
        ...base,
        registrations: [parseNativeHostManifest("chrome", "a", manifest("/foreign-changed"))],
        accepted,
      }).kind,
    ).toBe("needs-consent");
    expect(
      chromeLaunchDecision({
        ...base,
        registrations: [foreign],
        accepted: { ...accepted, providerInstanceId: "other" },
      }).kind,
    ).toBe("needs-consent");
  });
  it("is off when not certified and unknown when unreadable", () => {
    expect(chromeLaunchDecision({ ...base, certified: false, registrations: [] })).toEqual({
      kind: "off",
    });
    expect(
      chromeLaunchDecision({
        ...base,
        registrations: [{ browser: "chrome", location: "a", state: "unreadable" }],
      }),
    ).toMatchObject({ kind: "unknown" });
  });
  // The browser folders are macOS paths.
  it.skipIf(process.platform === "win32")(
    "covers seven deduplicated browser folders under the real home",
    () => {
      const locations = descriptor.locations("/profile/claude", "/Users/me");
      expect(locations).toHaveLength(7);
      expect(
        new Set(locations.map((entry) => (entry.kind === "file" ? entry.path : ""))).size,
      ).toBe(7);
      expect(locations[0]).toMatchObject({
        path: "/Users/me/Library/Application Support/Google/Chrome/NativeMessagingHosts/com.anthropic.claude_code_browser_extension.json",
      });
    },
  );
});

describe("manifest parsing", () => {
  it("keeps allowed origins and rejects malformed manifests", () => {
    const entry = parseNativeHostManifest(
      "chrome",
      "a",
      JSON.stringify({
        name: "h",
        type: "stdio",
        path: "/x",
        allowed_origins: ["chrome-extension://a/"],
      }),
    );
    expect(entry).toMatchObject({ state: "ok", allowedOrigins: ["chrome-extension://a/"] });
    expect(parseNativeHostManifest("chrome", "a", "not-json").state).toBe("malformed");
    expect(
      parseNativeHostManifest(
        "chrome",
        "a",
        JSON.stringify({ name: "h", type: "stdio", path: "/x", allowed_origins: [1] }),
      ).state,
    ).toBe("malformed");
  });
  it("parses default registry values including paths with spaces", () => {
    expect(
      parseChromeRegistryQuery(
        "HKEY_CURRENT_USER\\Key\r\n    (Default)    REG_SZ    C:\\Path With Spaces\\manifest.json\r\n",
      ),
    ).toBe("C:\\Path With Spaces\\manifest.json");
  });
});
